<?php
declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';require_admin();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);$current=(string)($_POST['current_password']??'');$password=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$s=db()->prepare('SELECT password_hash FROM admin_users WHERE id=?');$s->execute([(int)user()['id']]);$hash=(string)$s->fetchColumn();if(!password_verify($current,$hash))$error='كلمة المرور الحالية غير صحيحة.';elseif(strlen($password)<10)$error='كلمة المرور الجديدة يجب ألا تقل عن 10 محارف.';elseif($password!==$confirm)$error='تأكيد كلمة المرور غير مطابق.';else{$s=db()->prepare('UPDATE admin_users SET password_hash=?,must_change_password=0 WHERE id=?');$s->execute([password_hash($password,PASSWORD_DEFAULT),(int)user()['id']]);$_SESSION['user']['must_change_password']=false;$message='تم تغيير كلمة المرور بنجاح.';}}
page_header('الإعدادات','settings');
?><section class="panel narrow"><p class="eyebrow">الأمان</p><h2>تغيير كلمة المرور</h2><?php if($message):?><div class="alert success"><?= school_e($message) ?></div><?php endif;?><?php if($error):?><div class="alert error"><?= school_e($error) ?></div><?php endif;?><form method="post" class="form-grid password-form"><?= school_csrf_field() ?><label>كلمة المرور الحالية<input type="password" name="current_password" required autocomplete="current-password"></label><label>كلمة المرور الجديدة<input type="password" name="new_password" required minlength="10" autocomplete="new-password"></label><label>تأكيد كلمة المرور<input type="password" name="confirm_password" required minlength="10" autocomplete="new-password"></label><button class="button primary">تحديث كلمة المرور</button></form></section><?php page_footer(); ?>